     */
    public function getWeight(): ?float
    {
        return $this->container['weight'];
    }

    /**
     * Sets weight
     *
     * @param float|null $weight weight
     *
     * @return $this
     */
    public function setWeight(?float $weight): static
    {
        if (is_null($weight)) {
            throw new InvalidArgumentException('non-nullable weight cannot be null');
        }

        if (($weight > 1000000.0)) {
            throw new InvalidArgumentException('invalid value for $weight when calling CriterionIn., must be smaller than or equal to 1000000.0.');
        }
        if (($weight < 0.0)) {
            throw new InvalidArgumentException('invalid value for $weight when calling CriterionIn., must be bigger than or equal to 0.0.');
        }

        $this->container['weight'] = $weight;

        return $this;
    }
}


